properties.content:
# Set environment variables here.

# The java implementation to use. Java 1.6 required.
export JAVA_HOME={{java64_home}}

# Collector Log directory for log4j
export AMS_COLLECTOR_LOG_DIR={{ams_collector_log_dir}}

# Monitor Log directory for outfile
export AMS_MONITOR_LOG_DIR={{ams_monitor_log_dir}}

# Collector pid directory
export AMS_COLLECTOR_PID_DIR={{ams_collector_pid_dir}}

# Monitor pid directory
export AMS_MONITOR_PID_DIR={{ams_monitor_pid_dir}}

# AMS HBase pid directory
export AMS_HBASE_PID_DIR={{hbase_pid_dir}}

# AMS Collector heapsize
export AMS_COLLECTOR_HEAPSIZE={{metrics_collector_heapsize}}

# HBase compaction policy enabled
export AMS_HBASE_NORMALIZER_ENABLED={{ams_hbase_normalizer_enabled}}

# HBase compaction policy enabled
export AMS_HBASE_FIFO_COMPACTION_ENABLED={{ams_hbase_fifo_compaction_enabled}}

# AMS Collector options
export AMS_COLLECTOR_OPTS="-Djava.library.path=/usr/lib/ams-hbase/lib/hadoop-native"
{% if security_enabled %}
export AMS_COLLECTOR_OPTS="$AMS_COLLECTOR_OPTS -Djava.security.auth.login.config={{ams_collector_jaas_config_file}} -Dzookeeper.sasl.client.username={{zk_servicename}}"
{% endif %}

# AMS Collector GC options
export AMS_COLLECTOR_GC_OPTS="-XX:+UseConcMarkSweepGC -verbose:gc -XX:+PrintGCDetails -XX:+PrintGCDateStamps -Xloggc:{{ams_collector_log_dir}}/collector-gc.log-`date +'%Y%m%d%H%M'`"
export AMS_COLLECTOR_OPTS="$AMS_COLLECTOR_OPTS $AMS_COLLECTOR_GC_OPTS"

export JAVA_HOME={{java64_home}}
export ZOOKEEPER_HOME={{zk_home}}
export ZOO_LOG_DIR={{zk_log_dir}}
export ZOOPIDFILE={{zk_pid_file}}
export SERVER_JVMFLAGS={{zk_server_heapsize}}
export JAVA=$JAVA_HOME/bin/java
export CLASSPATH=$CLASSPATH:/usr/share/zookeeper/*

{% if security_enabled %}
export SERVER_JVMFLAGS="$SERVER_JVMFLAGS -Djava.security.auth.login.config={{zk_server_jaas_file}}"
export CLIENT_JVMFLAGS="$CLIENT_JVMFLAGS -Djava.security.auth.login.config={{zk_client_jaas_file}}"
{% endif %}

# Hive environment variables
export JAVA_HOME={{java64_home}}
export HIVE_HOME={{hive_home}}
export HIVE_CONF_DIR={{hive_conf_dir}}
export HIVE_LOG_DIR={{hive_log_dir}}
export HIVE_PID_DIR={{hive_pid_dir}}
export HIVE_AUX_JARS_PATH=

# Hive Server2 Heap Size
export HADOOP_HEAPSIZE={{hiveserver2_heapsize}}

# Metastore Heap Size
export HIVE_METASTORE_HEAPSIZE={{metastore_heapsize}}

# Hive CLI Heap Size
export HIVE_CLI_HEAPSIZE={{hive_heapsize}}

# Hive User
export HIVE_USER={{hive_user}}

# GC Options
export HIVE_SERVER2_OPTS="-XX:+UseConcMarkSweepGC -XX:ErrorFile={{hive_log_dir}}/hs_err_pid%p.log -Xloggc:{{hive_log_dir}}/gc.log-`date +'%Y%m%d%H%M'` -verbose:gc -XX:+PrintGCDetails -XX:+PrintGCDateStamps"
export HIVE_METASTORE_OPTS="-XX:+UseConcMarkSweepGC -XX:ErrorFile={{hive_log_dir}}/hs_err_pid%p.log -Xloggc:{{hive_log_dir}}/gc.log-`date +'%Y%m%d%H%M'` -verbose:gc -XX:+PrintGCDetails -XX:+PrintGCDateStamps"

# max open files
ulimit -n 32768 2>/dev/null || true

# max processes
ulimit -u 32768 2>/dev/null || true

# HBase environment variables
export JAVA_HOME={{java64_home}}
export HBASE_HOME={{hbase_home}}
export HBASE_CONF_DIR={{hbase_conf_dir}}
export HBASE_LOG_DIR={{hbase_log_dir}}
export HBASE_PID_DIR={{hbase_pid_dir}}

# Master heap size
export HBASE_MASTER_HEAPSIZE={{hbase_master_heapsize}}

# RegionServer heap size
export HBASE_REGIONSERVER_HEAPSIZE={{hbase_regionserver_heapsize}}

# Phoenix Query Server heap size
export PHOENIX_QUERYSERVER_HEAPSIZE={{phoenix_queryserver_heapsize}}

# HBase User
export HBASE_USER=hbase

# GC Options
export HBASE_MASTER_OPTS="-XX:+UseConcMarkSweepGC -XX:ErrorFile={{hbase_log_dir}}/hs_err_pid%p.log -Xloggc:{{hbase_log_dir}}/gc.log-`date +'%Y%m%d%H%M'` -verbose:gc -XX:+PrintGCDetails -XX:+PrintGCDateStamps -Xmn{{hbase_master_xmn_size}}"
export HBASE_REGIONSERVER_OPTS="-XX:+UseConcMarkSweepGC -XX:ErrorFile={{hbase_log_dir}}/hs_err_pid%p.log -Xloggc:{{hbase_log_dir}}/gc.log-`date +'%Y%m%d%H%M'` -verbose:gc -XX:+PrintGCDetails -XX:+PrintGCDateStamps -Xmn{{regionserver_xmn_size}}"
export PHOENIX_QUERYSERVER_OPTS="-XX:+UseConcMarkSweepGC -XX:ErrorFile={{hbase_log_dir}}/hs_err_pid%p.log -Xloggc:{{hbase_log_dir}}/gc.log-`date +'%Y%m%d%H%M'` -verbose:gc -XX:+PrintGCDetails -XX:+PrintGCDateStamps -Xms{{phoenix_queryserver_heapsize}} -Xmx{{phoenix_queryserver_heapsize}}"

# max open files
ulimit -n {{max_open_files_limit}} 2>/dev/null || true

# max processes
ulimit -u 32768 2>/dev/null || true

# Disable IPv6
export HBASE_OPTS="-Djava.net.preferIPv4Stack=true ${HBASE_OPTS}"

# Infra Solr environment variables
export JAVA_HOME={{java64_home}}
export INFRA_SOLR_HOME={{infra_solr_home}}
export INFRA_SOLR_CONF_DIR={{infra_solr_conf_dir}}
export INFRA_SOLR_LOG_DIR={{infra_solr_log_dir}}
export INFRA_SOLR_PID_DIR={{infra_solr_pid_dir}}

# Infra Solr heap size
export INFRA_SOLR_HEAPSIZE={{infra_solr_heapsize}}

# GC Options
export INFRA_SOLR_OPTS="-XX:+UseConcMarkSweepGC -XX:ErrorFile={{infra_solr_log_dir}}/hs_err_pid%p.log -Xloggc:{{infra_solr_log_dir}}/gc.log-`date +'%Y%m%d%H%M'` -verbose:gc -XX:+PrintGCDetails -XX:+PrintGCDateStamps"

# max open files
ulimit -n 65536 2>/dev/null || true

# max processes
ulimit -u 32768 2>/dev/null || true

